import {GYM_CONNECTOR} from '../gym/layout.js';
import {toWorld} from '../world/coordinates.js';
import * as THREE from 'three';import {zoneBounds,ZONES} from '../world/connected-layout.js';
// On desktop the controls occupy the corners; reserving their entire bottom row shrank
// the office desk to 161px versus the supplied ~222px reference at 1869×861.
const PRINCIPAL_DESKTOP_FRAME={minWidth:960,paddingPx:{left:16,right:16,top:20,bottom:80}};
/** Keep the selected room isolated, but spend the first view on its occupied interior. */
export function schoolRoomFraming(id,{fullRoom=false}={}){const b=zoneBounds(id);if(!b)return null;const field=id==='sportsField';if(id==='schoolGym'&&!fullRoom){const p=toWorld(id,{x:-3,z:11});return {camera:{position:[p.x+5.5,9,p.z+10],portraitPosition:[p.x-9,7,p.z+7],target:[p.x,2,p.z],span:10,follow:true,focusPlayer:true,focusHeight:16,followBounds:{...b,minX:b.minX+3,maxX:b.maxX-3,minZ:b.minZ+3,maxZ:b.maxZ-2}},bounds:new THREE.Box3(new THREE.Vector3(p.x-5,-.16,p.z-4),new THREE.Vector3(p.x+5,3.2,p.z+4)),zoom:1.5};}const fit=field&&!fullRoom?{...b,maxX:ZONES.sportsField.x+7.5}:b,x=(fit.minX+fit.maxX)/2,z=(fit.minZ+fit.maxZ)/2;return{camera:{position:(field||id==='library')?[x+7.5,12,z+15]:(()=>{const p=toWorld(id,{x:['korean','english'].includes(id)?4:7.5,z:['korean','english'].includes(id)?17:15});return[p.x,12,p.z];})(),portraitPosition:(field||id==='library')?[x+2.6,14,z+17]:(()=>{const p=toWorld(id,{x:2.6,z:17});return[p.x,14,p.z];})(),target:[x,['korean','english'].includes(id)?1.3:.65,z],span:10,follow:field,...(id==='principalOffice'?{interiorFrame:PRINCIPAL_DESKTOP_FRAME}:{}),...(field?{focusScale:2,focusHeight:45,focusPlayer:true,followBounds:{...b,minZ:Math.min(b.minZ,GYM_CONNECTOR.minZ)}}:{})},bounds:new THREE.Box3(new THREE.Vector3(fit.minX,-.16,fit.minZ),new THREE.Vector3(fit.maxX,['math','socialStudies'].includes(id)?4.15:id==='principalOffice'?3.55:['korean','english','computerLab'].includes(id)?3.45:3.1,fit.maxZ)),zoom:field?1.5:['korean','english'].includes(id)?1.1:id==='principalOffice'?1.15:id==='library'?1.30:1.25};}
